    { term: "Nigus Sahle Sellase", def: "The Shewan ruler (r. 1813-1847) under whom the kingdom reached its heyday and opened relations with Britain and France." },
    { term: "Isolation", def: "The condition of Shewa's distance from the wars of the Zemene-Mesafint, which allowed it to grow strong in peace." }
